:DiabeticPatient owl:equivalentClass [
  owl:intersectionOf ( :Patient
    [ a owl:Restriction ;
      owl:onProperty :hasDiagnosis ;
      owl:someValuesFrom :Diabetes ] ) ] .

:InpatientShape a sh:NodeShape ;
  sh:targetClass :Inpatient ;
  sh:property [ sh:path :attendingPhysician ;
    sh:minCount 1 ; sh:maxCount 1 ] .
